function ensureThemeDialog(){if($('#theme-dialog'))return;const dialog=document.createElement('dialog');dialog.id='theme-dialog';dialog.className='dialog theme-dialog';dialog.innerHTML='<form method="dialog"><button class="dialog-close" value="cancel" type="button" aria-label="Zamknij">×</button><p class="eyebrow">WYGLĄD</p><h2>Wybierz motyw Chronizo</h2><div class="theme-options"><button type="button" data-theme-choice="shield"><i></i><b>Tarcza Kapitana</b><small>Czerwień, biel i granat</small></button><button type="button" data-theme-choice="green"><i></i><b>Zielony Chronizo</b><small>Dotychczasowy wygląd</small></button><button type="button" data-theme-choice="dark"><i></i><b>Ciemny</b><small>Neutralna nocna kronika</small></button><button type="button" data-theme-choice="light"><i></i><b>Jasny</b><small>Do czytania w dzień</small></button></div></form>';document.body.append(dialog);dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.querySelectorAll('[data-theme-choice]').forEach(button=>button.onclick=()=>{applyTheme(button.dataset.themeChoice);dialog.close()})}
