function migrateLegacySourceTags(){let changed=false;for(const project of state.projects){for(const source of project.sources||[]){const keys=[source.importKey,...(source.importKeys||[])].filter(Boolean),tags=sourceTags(source),legacyTag=source.importOrigin==='Extended VO'||keys.some(key=>key.startsWith('extended-vo-'))?'EMCU':source.importOrigin==='Multiversal VO'||keys.some(key=>key.startsWith('multiversal-vo-'))?'MVO':null;if(legacyTag&&!tags.includes(legacyTag)){source.tags=[...tags,legacyTag];changed=true}for(const key of keys){const position=importSheetPosition(key);if(position)changed=rememberSheetPosition(source,position.tag,position.row)||changed}}}if(changed)save()}
