async function enrichSourceMetadata(){try{const response=await fetch('data/source-metadata.json?v=1');if(!response.ok)return;const metadata=await response.json();if(metadata.format!=='chronizo-source-metadata')return;const releases=new Map();for(const release of metadata.releases||[]){const key=metadataKey(release.title);if(!releases.has(key))releases.set(key,release)}const universes=new Map();for(const universe of metadata.universes||[])for(const key of universeMetadataAliases(universe.designation))if(!universes.has(key))universes.set(key,universe);let changed=false;for(const project of state.projects){for(const source of project.sources||[]){const imported=[source.importKey,...(source.importKeys||[])].some(key=>importSheetPosition(key));if(!imported||source.releaseDate)continue;const release=releases.get(metadataKey(source.title)),date=releaseDateIso(release?.date);if(date){source.releaseDate=date;source.releaseOrderRow=release.row;changed=true}}for(const world of project.worlds||[]){const importedDescription=!world.description||/ · import$/i.test(world.description);if(!importedDescription)continue;const universe=universes.get(universeMetadataKey(worldLabel(world)));if(universe?.description&&world.description!==universe.description){world.description=universe.description;world.universeIndexRow=universe.row;changed=true}}}if(changed){save();render()}}catch(error){console.warn('Chronizo metadata enrichment skipped',error)}}
function sourceTagMarkup(source){return sourceTags(source).map(tag=>`<span class="tag source-hashtag">#${escapeHtml(tag)}</span>`).join('')}
function sourcePalette(source){const medium={Film:'#2f76ff',Serial:'#8b5cf6',Komiks:'#ef4444',Książka:'#d79b19',Gra:'#18a96b',Inne:'#32a4ad'},tag={EMCU:'#2374d8',MVO:'#8a4fd1'},colors=sourceColorMode==='tag'?sourceTags(source).map(name=>tag[name]||'#38bfa1'):[medium[source.type]||medium.Inne],strength=source.status==='Ukończone'||source.status==='Opracowane'?42:source.status==='Rozpoczęte'?24:9,mixes=(colors.length?colors:['#32a4ad']).map(color=>`color-mix(in srgb,${color} ${strength}%,var(--panel2))`);return `--source-bg:${mixes.length>1?`linear-gradient(120deg,${mixes.join(',')})`:mixes[0]};--source-accent:${colors[0]||'#32a4ad'}`}
