function roadNode(item,index){if(roadMode==='sources')return `<article class="road-node source-item ${index%2?'branch-down':'branch-up'}" style="${sourcePalette(item)}"><span class="road-dot"></span><small>${dateLabel(item.date,item.dateApprox)}</small><b>${escapeHtml(item.title)}</b><em>${escapeHtml(item.type)} · ${escapeHtml(item.status)}<br>${releaseLabel(item.releaseDate)}</em><div class="tag-row">${sourceTagMarkup(item)}</div>${itemActions('source',item.id)}</article>`;const sources=eventSources(item),characters=projectCharacters().filter(character=>(item.characterIds||[]).includes(character.id));return `<article class="road-node ${index%2?'branch-down':'branch-up'}"><span class="road-dot"></span><small>${dateLabel(eventChronologyDate(item),item.timeType==='approx')}</small><b>${escapeHtml(item.title)}</b><em>${escapeHtml([item.world,item.place,...sources.map(source=>source.title)].filter(Boolean).join(' · ')||'Bez przypisania')}</em>${characters.length?`<span class="road-people">${characters.map(character=>escapeHtml(character.name)).join(' · ')}</span>`:''}${itemActions('event',item.id)}</article>`}
function roadItemsMarkup(items){if(roadMode!=='sources')return items.map(roadNode).join('');const groups=new Map();for(const source of items){const worlds=sourceWorldLabels(source).sort(),key=worlds.length?worlds.join(' + '):'Bez przypisanego świata';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(source)}return [...groups].sort(([a],[b])=>a.localeCompare(b,'pl')).map(([world,sources])=>`<section class="road-world-lane"><h3>${sources.some(source=>sourceWorldLabels(source).length>1)?'⇄ Połączenie · ':''}${escapeHtml(world)} <span>${sources.length}</span></h3><div class="road-lane-scroll"><div class="road-lane-track">${sources.map(roadNode).join('')}</div></div></section>`).join('')}
function exportProject(){const project=activeProject();if(!project)return;const payload={format:'chronizo-project',version:1,exportedAt:new Date().toISOString(),project},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=(project.name||'chronizo').replace(/[^a-z0-9ąćęłńóśźż-]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()+'.chronizo.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importProjectFile(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const payload=JSON.parse(reader.result),source=payload.format==='chronizo-project'?payload.project:payload;if(!source||typeof source.name!=='string'||!Array.isArray(source.sources)||!Array.isArray(source.events))throw new Error('Nieprawidłowy format');const project=structuredClone(source);project.id=uid('project');project.name=source.name+' · import';project.worlds=Array.isArray(project.worlds)?project.worlds:[];project.characters=Array.isArray(project.characters)?project.characters:[];state.projects.push(project);state.activeProjectId=project.id;save();render();switchView('road')}catch{alert('Nie udało się wczytać projektu. Wybierz plik JSON wyeksportowany z Chronizo.')}};reader.readAsText(file)}
function extendedUniverseLabels(value=''){return String(value).split('/').map(part=>part.trim()).filter(Boolean).map(part=>part==='FW'?'Framework':/^\d+[✩★]?$/.test(part)?`Earth-${part}`:part)}
