async function importSourcePack({url,buttonId,label,tag}){const project=activeProject(),button=$(buttonId);if(!project)return openDialog('#project-dialog');button.disabled=true;button.textContent=`Wczytuję ${label}…`;try{const response=await fetch(url);if(!response.ok)throw new Error('Nie udało się pobrać paczki');const pack=await response.json();if(pack.format!=='chronizo-source-pack'||!Array.isArray(pack.sources))throw new Error('Nieprawidłowa paczka źródeł');let added=0,merged=0,worldsAdded=0;for(const packed of pack.sources){const labels=extendedUniverseLabels(packed.universe),worldIds=[];for(const designation of labels){let world=projectWorlds().find(item=>worldLabel(item).toLowerCase()===designation.toLowerCase());if(!world){world={id:uid('world'),designation,name:designation,description:`${label} · import`};projectWorlds().push(world);worldsAdded++}worldIds.push(world.id)}const identity=sourceIdentity(packed.title,packed.date,labels),byImport=(project.sources||[]).find(source=>source.importKey===packed.importKey||(source.importKeys||[]).includes(packed.importKey)),existing=byImport||(project.sources||[]).find(source=>sourceIdentity(source.title,source.date,sourceWorldLabels(source))===identity);if(existing){existing.tags=[...new Set([...sourceTags(existing),...(packed.tags||[]),tag].filter(Boolean))];existing.importKeys=[...new Set([...(existing.importKeys||[]),existing.importKey,packed.importKey].filter(Boolean))];existing.worldIds=[...new Set([...(existing.worldIds||[]),...worldIds])];rememberSheetPosition(existing,tag,packed.row);merged++;continue}project.sources.push({id:uid('source'),importKey:packed.importKey,importKeys:[packed.importKey],importOrigin:label,title:packed.title,type:packed.type||'Inne',status:'Nierozpoczęte',date:packed.date||'',dateApprox:Boolean(packed.dateApprox),releaseDate:packed.releaseDate||'',tags:[...new Set([...(packed.tags||[]),tag].filter(Boolean))],sheetRows:{[tag]:Number(packed.row)},worldIds,createdAt:new Date().toISOString()});added++}save();render();switchView('sources');alert(`${label}: dodano ${added}, połączono lub zaktualizowano ${merged}, utworzono ${worldsAdded} światów.`)}catch(error){alert(`Import ${label} nie powiódł się: ${error.message}`)}finally{button.disabled=false;button.textContent=`↓ Wczytaj ${label}`}}
async function importSourcePackFast({url,buttonId,label,tag}){
 const project=activeProject(),button=$(buttonId);
 if(!project)return openDialog('#project-dialog');
 button.disabled=true;button.textContent=`Wczytuję ${label}…`;
 try{
  const response=await fetch(url);if(!response.ok)throw new Error('Nie udało się pobrać paczki');
  const pack=await response.json();if(pack.format!=='chronizo-source-pack'||!Array.isArray(pack.sources))throw new Error('Nieprawidłowa paczka źródeł');
  const worlds=projectWorlds(),worldMap=new Map(worlds.map(world=>[worldLabel(world).toLowerCase(),world])),imports=new Map(),identities=new Map();
  for(const source of project.sources||[]){for(const key of [source.importKey,...(source.importKeys||[])].filter(Boolean))imports.set(key,source);identities.set(sourceIdentity(source.title,source.date,sourceWorldLabels(source)),source)}
  let added=0,merged=0,worldsAdded=0;
  for(const packed of pack.sources){
   const labels=extendedUniverseLabels(packed.universe),identity=sourceIdentity(packed.title,packed.date,labels);
   const existing=imports.get(packed.importKey)||identities.get(identity);
   if(existing){existing.tags=[...new Set([...sourceTags(existing),...(packed.tags||[]),tag].filter(Boolean))];existing.importKeys=[...new Set([...(existing.importKeys||[]),existing.importKey,packed.importKey].filter(Boolean))];rememberSheetPosition(existing,tag,packed.row);imports.set(packed.importKey,existing);identities.set(identity,existing);merged++;continue}
   const worldIds=[];
   for(const designation of labels){const key=designation.toLowerCase();let world=worldMap.get(key);if(!world){world={id:uid('world'),designation,name:designation,description:`${label} · import`};worlds.push(world);worldMap.set(key,world);worldsAdded++}worldIds.push(world.id)}
   const created={id:uid('source'),importKey:packed.importKey,importKeys:[packed.importKey],importOrigin:label,title:packed.title,type:packed.type||'Inne',status:'Nierozpoczęte',date:packed.date||'',dateApprox:Boolean(packed.dateApprox),releaseDate:packed.releaseDate||'',tags:[...new Set([...(packed.tags||[]),tag].filter(Boolean))],sheetRows:{[tag]:Number(packed.row)},worldIds,createdAt:new Date().toISOString()};
   project.sources.push(created);imports.set(packed.importKey,created);identities.set(identity,created);added++;
  }
  save();render();switchView('sources');void enrichSourceMetadata();alert(`${label}: dodano ${added}, połączono lub oznaczono hashtagami ${merged}, utworzono ${worldsAdded} światów.`);
 }catch(error){alert(`Import ${label} nie powiódł się: ${error.message}`)}
 finally{button.disabled=false;button.textContent=`↓ Wczytaj ${label}`}
}
