function ensureRelationPicker(){if($('#event-relation-picker'))return;const panel=document.createElement('section');panel.id='event-relation-picker';panel.className='relation-picker';panel.hidden=true;panel.innerHTML='<div class="relation-head"><div><b>Wybierz powiązane wydarzenie</b><small>Wyszukaj nazwę, postać, tag, świat lub miejsce</small></div><span id="relation-count"></span></div><input id="event-relation-search" type="search" autocomplete="off" placeholder="Szukaj wydarzenia lub osoby…"><div id="event-relation-results" class="relation-results"></div><p id="event-relation-error" class="relation-error" hidden>Wybierz wydarzenie, z którym tworzysz relację.</p>';const anchor=$('#event-world').closest('.form-row');anchor.before(panel);$('#event-relation-search').addEventListener('input',renderRelationPicker)}
function relationHaystack(event){const names=projectCharacters().filter(character=>(event.characterIds||[]).includes(character.id)).flatMap(character=>[character.name,...characterAliases(character)]);return [event.title,event.world,event.place,event.notes,...eventSources(event).map(source=>source.title),...names,...(event.tags||[])].filter(Boolean).join(' ').toLowerCase()}
function renderRelationPicker(){const panel=$('#event-relation-picker');if(!panel)return;const type=$('#event-time-type').value,visible=RELATION_TYPES.has(type);panel.hidden=!visible;if(!visible){selectedRelationId=null;return}const project=activeProject(),query=$('#event-relation-search').value.trim().toLowerCase(),events=(project?.events||[]).filter(event=>!query||relationHaystack(event).includes(query)),sources=project?.sources||[],groups=new Map();events.forEach(event=>{const key=event.sourceId||'';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(event)});$('#relation-count').textContent=events.length+' wyników';const results=$('#event-relation-results');if(!events.length){results.innerHTML='<div class="relation-empty">Nie znaleziono pasującego wydarzenia.</div>';return}const ordered=[...sources.map(source=>source.id),''].filter((id,index,array)=>groups.has(id)&&array.indexOf(id)===index);results.innerHTML=ordered.map(sourceId=>{const source=sources.find(item=>item.id===sourceId),items=groups.get(sourceId)||[];return `<div class="relation-group"><p>${escapeHtml(source?.title||'Bez przypisanego źródła')}</p>${items.map(event=>`<button class="relation-option${event.id===selectedRelationId?' selected':''}" type="button" data-event-id="${event.id}"><b>${escapeHtml(event.title)}</b><small>${escapeHtml([...(event.tags||[]),event.world,event.place].filter(Boolean).join(' · ')||'Bez dodatkowych tagów')}</small></button>`).join('')}</div>`}).join('');results.querySelectorAll('.relation-option').forEach(button=>button.addEventListener('click',()=>{selectedRelationId=button.dataset.eventId;$('#event-relation-error').hidden=true;renderRelationPicker()}))}
function openEventDialog(eventId=null){if(!activeProject())return openDialog('#project-dialog');editingEventId=eventId;ensureWorldFields();$('#event-form').reset();$('#event-inbox').checked=true;selectedRelationId=null;populateEventSources();ensureCharacterFields();ensureRelationPicker();$('#event-relation-search').value='';if(eventId){const item=activeProject().events.find(event=>event.id===eventId);if(item){$('#event-title').value=item.title;$('#event-source').value=item.sourceId||'';$('#event-time-type').value=item.timeType||'unknown';$('#event-date').value=item.date||'';$('#event-world').value=item.world||'';$('#event-place').value=item.place||'';$('#event-tags').value=(item.tags||[]).join(', ');$('#event-notes').value=item.notes||'';$('#event-inbox').checked=Boolean(item.inbox);selectedRelationId=item.relationEventId||null;$('#event-dialog h2').textContent='Edytuj wydarzenie';$('#event-form .primary-button').textContent='Zapisz zmiany';$('#event-extra-sources').querySelectorAll('input').forEach(input=>input.checked=eventSourceIds(item).includes(input.value)&&input.value!==item.sourceId);$('#event-world-links').querySelectorAll('input').forEach(input=>input.checked=(item.worldLinks||[]).includes(input.value));$('#event-characters').querySelectorAll('input').forEach(input=>input.checked=(item.characterIds||[]).includes(input.value))}}else{$('#event-dialog h2').textContent='Co się wydarzyło?';$('#event-form .primary-button').textContent='Zapisz i dodaj następne'}renderEventDateField();renderRelationPicker();openDialog('#event-dialog')}

