$('#project-select').addEventListener('change',event=>{state.activeProjectId=event.target.value||null;save();render()});
$('.main').addEventListener('click',event=>{const button=event.target.closest('button[data-id]');if(!button)return;const project=activeProject(),id=button.dataset.id;if(button.classList.contains('edit-source'))openSourceDialog(id);if(button.classList.contains('edit-event'))openEventDialog(id);if(button.classList.contains('edit-character'))openCharacterDialog(id);if(button.classList.contains('delete-source')&&confirm('Usunąć to źródło? Powiązane wydarzenia pozostaną w projekcie.')){project.sources=project.sources.filter(source=>source.id!==id);project.events.forEach(item=>{if(item.sourceId===id)item.sourceId=null;item.sourceIds=eventSourceIds(item).filter(sourceId=>sourceId!==id)});save();render()}if(button.classList.contains('delete-event')&&confirm('Usunąć to wydarzenie?')){project.events=project.events.filter(item=>item.id!==id);project.events.forEach(item=>{if(item.relationEventId===id)item.relationEventId=null});save();render()}if(button.classList.contains('delete-character')&&confirm('Usunąć tę postać? Zniknie także z przypisanych wydarzeń.')){project.characters=projectCharacters().filter(character=>character.id!==id);project.events.forEach(item=>item.characterIds=(item.characterIds||[]).filter(characterId=>characterId!==id));save();render()}});
$('#project-form').addEventListener('submit',event=>{if(event.submitter?.value!=='save')return;event.preventDefault();const name=$('#project-name').value.trim();if(!name)return;const project={id:uid('project'),name,description:$('#project-description').value.trim(),createdAt:new Date().toISOString(),worlds:[],sources:[],characters:[],events:[]};state.projects.push(project);state.activeProjectId=project.id;save();event.currentTarget.reset();$('#project-dialog').close();render();switchView('road')});
$('#source-form').addEventListener('submit',event=>{if(event.submitter?.value!=='save')return;event.preventDefault();const project=activeProject(),title=$('#source-title').value.trim();if(!project||!title)return;const data={title,type:$('#source-type').value,status:$('#source-status').value,date:$('#source-date')?.value||'',dateApprox:$('#source-date-approx')?.checked||false,releaseDate:$('#source-release-date')?.value||'',worldIds:[...$('#source-worlds').querySelectorAll('input:checked')].map(input=>input.value)};let sourceId=editingSourceId;if(editingSourceId){const item=project.sources.find(source=>source.id===editingSourceId);if(item)Object.assign(item,data)}else{sourceId=uid('source');project.sources.push({id:sourceId,...data,createdAt:new Date().toISOString()})}const target=sourceDialogTarget;editingSourceId=null;sourceDialogTarget=null;save();event.currentTarget.reset();$('#source-dialog').close();render();if(target==='event'){populateEventSources();$('#event-source').value=sourceId;ensureCharacterFields()}else switchView('road')});
$('#event-form').addEventListener('submit',event=>{if(event.submitter?.value!=='save')return;event.preventDefault();const project=activeProject(),title=$('#event-title').value.trim(),timeType=$('#event-time-type').value;if(!project||!title)return;if(RELATION_TYPES.has(timeType)&&!selectedRelationId){$('#event-relation-error').hidden=false;$('#event-relation-picker').scrollIntoView({block:'nearest'});return}const sourceId=$('#event-source').value||null,extraSources=[...$('#event-extra-sources').querySelectorAll('input:checked')].map(input=>input.value).filter(id=>id!==sourceId),data={title,sourceId,sourceIds:[sourceId,...extraSources].filter(Boolean),characterIds:[...$('#event-characters').querySelectorAll('input:checked')].map(input=>input.value),timeType,date:$('#event-date')?.value||'',relationEventId:selectedRelationId,world:$('#event-world').value.trim(),worldLinks:[...$('#event-world-links').querySelectorAll('input:checked')].map(input=>input.value),place:$('#event-place').value.trim(),tags:$('#event-tags').value.split(',').map(tag=>tag.trim()).filter(Boolean),notes:$('#event-notes').value.trim(),inbox:$('#event-inbox').checked};if(editingEventId){const item=project.events.find(existing=>existing.id===editingEventId);if(item)Object.assign(item,data);editingEventId=null;save();$('#event-dialog').close();render();return}project.events.push({id:uid('event'),...data,createdAt:new Date().toISOString()});save();event.currentTarget.reset();selectedRelationId=null;populateEventSources();ensureCharacterFields();$('#event-source').value=sourceId||'';$('#event-inbox').checked=true;renderEventDateField();renderRelationPicker();render();$('#event-title').focus()});

